#!/usr/bin/env node
// One-off: record RETRO sub_agent_execution_results evidence for
// SD-LEO-FIX-POST-TOOL-LOOP-001's PLAN-TO-LEAD handoff. The retrospective row
// (9342cbe0-7164-49db-b092-7e7a331eda94) already exists (generated by the
// retro-agent via Task tool), but a Task-tool sub-agent alone does not write
// sub_agent_execution_results -- this uses the same storeSubAgentResults +
// resolveRepo pattern as scripts/record-explore-evidence.js.
import { storeSubAgentResults } from '../../lib/sub-agent-executor/results-storage.js';
import { resolveSubAgentRepo, applySubAgentRepoVerdict } from '../../lib/sub-agents/resolve-repo.js';
import { getSupabaseClient } from '../../lib/sub-agent-executor/supabase-client.js';
import { isMainModule } from '../../lib/utils/is-main-module.js';

const SD_ID = 'SD-LEO-FIX-POST-TOOL-LOOP-001';
const RETRO_ID = '9342cbe0-7164-49db-b092-7e7a331eda94';

async function main() {
  const supabase = await getSupabaseClient();
  const { data: sd } = await supabase
    .from('strategic_directives_v2')
    .select('target_application')
    .eq('sd_key', SD_ID)
    .maybeSingle();

  const resolution = await resolveSubAgentRepo({
    sdId: SD_ID,
    targetApplication: sd?.target_application || null,
    subAgentCode: 'RETRO',
    supabase,
  });

  const results = {
    verdict: 'PASS',
    confidence: 95,
    summary: 'Retrospective published (row 9342cbe0-7164-49db-b092-7e7a331eda94, quality_score 100). '
      + 'Key finding: sensitive-path eligibility preflight (lib/quick-fix/sensitive-path-registry.js) only '
      + 'runs at QF-completion time, not creation/claim time, so a worker can invest a full build+test+merge '
      + 'cycle before discovering a QF must escalate to a full SD -- action item filed. Correctly '
      + 'distinguished the RCA-refuted updated_at instrument-error symptom from the genuine setLoopState '
      + 'defect. Caught and corrected a 150/150-vs-131/131 test-count inaccuracy in this SD\'s own deliverable notes.',
    findings: [
      'Sensitive-path preflight timing gap: evaluateQfEligibilityPreflight only fires at QF completion; earlier detection was possible since the QF description named the disqualifying file at creation.',
      'Instrument-error-vs-defect discrimination handled correctly: updated_at non-advancement excluded from scope; setLoopState COUNT_UNMEASURABLE root-caused and fixed.',
      'Data-hygiene: an SD-side deliverable completion_notes cited 150/150 tests; actual TESTING evidence is 131/131 (5 collectible files, 1 quarantined) -- corrected in-session.',
      'lib/deliverables/mark-hand-completed.js currently PGRST204s on live schema (references staged completed_at column from unapplied chairman-gated migration 20260905_add_deliverables_provenance.sql) -- disclosed, pre-existing, out of scope for this SD.'
    ],
    metadata: {
      recorded_by: 'scripts/one-off/_record-retro-evidence-sd-leo-fix-post-tool-loop-001.mjs',
      retrospective_id: RETRO_ID,
      producer_note: 'RETRO generated via Task-tool retro-agent, which does not write sub_agent_execution_results itself; this is the sanctioned transcription path (mirrors scripts/record-explore-evidence.js).'
    }
  };
  applySubAgentRepoVerdict(results, resolution);

  const stored = await storeSubAgentResults('RETRO', SD_ID, null, results, { phase: 'PLAN' });

  const { data, error } = await supabase
    .from('sub_agent_execution_results')
    .select('id,sub_agent_code,phase,verdict,created_at')
    .eq('id', stored.id)
    .maybeSingle();

  if (error || !data) {
    console.error(`WROTE but could not read back id=${stored?.id}: ${error?.message || 'no row'}`);
    process.exit(1);
  }
  console.log('RETRO evidence recorded and read back:', JSON.stringify(data, null, 2));
}

if (isMainModule(import.meta.url)) {
  main().catch((e) => { console.error('FATAL', e); process.exitCode = 1; });
}
